INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Счет Трейд Ресурс УТ-68 13.10 полный в загрузку OData', 'Полный счёт ООО «Эй Джи Групп» № УТ-68 от 13.10.2026 на 15 500 000,00 руб., правило «Создание файла для OData». Восемь колонок: Артикул (колонка счёта, текстом), Штрихкод (пусто), Наименование, Количество, Цена с НДС 22% (как в счёте), Страна, Номер ГТД, Номер РНПТ (пусто — нет в счёте). 47 строк в порядке счёта, 54 672 шт. Расхождение: строка 39 (KB85-25022111) цена 79,81 × 143 = 11 412,83, в счёте сумма 11 413,00 — цена оставлена как в счёте по решению пользователя, поэтому итог по файлу 15 499 999,83 руб. (на 0,17 руб. меньше счёта).', '/converted/schet-treid-resurs-ut-68-13-10-polnyj-v-zagruzku-odata.xlsx', 'Счет Трейд Ресурс УТ-68 13.10 полный в загрузку OData.xlsx', 'converted/schet-treid-resurs-ut-68-13-10-polnyj-v-zagruzku-odata.xlsx', 8437);